def parse_system_cfg(text):
    """/data/config/system.cfg -> dict。正常为 JSON；解析失败时用正则兜底取关键字段。"""
    try:
        return json.loads(text)
    except (ValueError, TypeError):
        out = {}
        for k in ("CUR_VERSION", "ROBOT_SERIES", "SN", "environment_name"):
            m = re.search(rf'"{k}"\s*:\s*"([^"]*)"', text or "")
            if m:
                out[k] = m.group(1)
        return out


def parse_mode(text):
    """mission_manager 日志 -> (mode, abnormal_service)，取最后一次出现的。

